import{_ as a,C as n,o as s,c as r,j as t,a as i,E as c,a2 as p}from"./chunks/framework.sc8Z_ZE3.js";const v=JSON.parse('{"title":"Spec Studio","description":"","frontmatter":{},"headers":[],"relativePath":"work/spec-studio.md","filePath":"work/spec-studio.md"}'),d={name:"work/spec-studio.md"};function h(l,e,u,m,g,w){const o=n("Badge");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"spec-studio",tabindex:"-1"},[i("Spec Studio "),t("a",{class:"header-anchor",href:"#spec-studio","aria-label":'Permalink to "Spec Studio"'},"​")],-1)),c(o,{type:"built",text:"Built"}),e[1]||(e[1]=p(' See the spec instead of reading it: decide, comment on a live mock and approve. Every decision is written into <code>SPEC.md</code>. Used in test runs so far, not yet in real team runs.<p>The <strong>Spec writing</strong> workflow opens the Spec Studio when the spec is ready. The run card links it (&quot;Review and approve the spec in the Spec Studio&quot;), and the run waits with <strong>Waiting for spec approval</strong>. The product owner gets one notification per wait.</p><h2 id="the-page" tabindex="-1">The page <a class="header-anchor" href="#the-page" aria-label="Permalink to &quot;The page&quot;">​</a></h2><ol><li><strong>Overview</strong> of the spec.</li><li><strong>Design: change it and see it</strong>: a live mock of the screens. Choose the style direction, fonts and corners; switch screen, device (desktop or phone), theme, and data (with data or empty). A contrast check shows whether text passes WCAG AA (4.5:1).</li><li><strong>Questions for you</strong>: each open question with the proposal preselected.</li><li><strong>Rules with examples</strong>: each worked example becomes a test.</li><li><strong>Acceptance criteria</strong>.</li><li><strong>Approve</strong>.</li></ol><h2 id="comment-on-the-mock" tabindex="-1">Comment on the mock <a class="header-anchor" href="#comment-on-the-mock" aria-label="Permalink to &quot;Comment on the mock&quot;">​</a></h2><p><strong>Comment</strong> turns on comment mode: tap the place in the mock you mean, then write what should change. You can also add a note to an element. <strong>Stop commenting</strong> ends it.</p><h2 id="approve" tabindex="-1">Approve <a class="header-anchor" href="#approve" aria-label="Permalink to &quot;Approve&quot;">​</a></h2><p>The approve section counts what you changed: decisions, notes on the mock, criteria to change, open points, and the contrast in light and dark. Open points block approval.</p><ul><li><strong>Approve spec vN and start the stories</strong> freezes this version and its mock as the <strong>review baseline</strong>, writes the decisions into <code>SPEC.md</code> and starts the stories.</li><li><strong>Send to revision</strong> sends it back with your notes.</li></ul><p>The later review compares the built screens against that baseline.</p><h2 id="on-a-phone" tabindex="-1">On a phone <a class="header-anchor" href="#on-a-phone" aria-label="Permalink to &quot;On a phone&quot;">​</a></h2><p>Desktop and phone are one page: one column on a phone, every tap target at least 44 px, and the desktop mock fully visible, scaled to the width.</p><h2 id="unattended-runs" tabindex="-1">Unattended runs <a class="header-anchor" href="#unattended-runs" aria-label="Permalink to &quot;Unattended runs&quot;">​</a></h2><p>By default the run waits for the product owner. A Workspace can let a passed review accept the spec without a person, through the API setting <code>spec_approval: &quot;review_passed&quot;</code> (audited). There is no screen for it yet.</p>',16))])}const f=a(d,[["render",h]]);export{v as __pageData,f as default};
